//! 🔀️ Variant schema selection retains original discriminators and paid matcher custody.
use super::*;
use semio_framework_value_native_source::NativeTreeKind;
fn nested(mut d:RetirementDemand)->Result<RetirementDemand,ValueError>{d.depth=d.depth.checked_add(1).ok_or_else(invalid)?;Ok(d)}
fn child(mut g:RetainedCloneGrant)->RetainedCloneGrant{g.maximum_depth=g.maximum_depth.saturating_sub(1);g}
fn progress(copy:usize)->RetainedCloneProgress{RetainedCloneProgress{copied_items:usize::from(copy!=0),copied_bytes:copy,..Default::default()}}
#[derive(Clone,Copy)]pub struct NativeVariantSpec{pub all:fn(usize)->Option<NativeRecordSchema>,pub units:fn(usize)->Option<NativeRecordSchema>,pub data:fn(usize)->Option<NativeRecordSchema>,pub count:usize,pub tag:Option<fn(usize)->Option<NativeRecordSchema>>}
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub struct NativeVariantSelection{pub index:usize,pub direct:bool}
pub struct NativeVariantSelector<I:NativeValueSource+?Sized>{binding:Option<RetainedCloneBinding>,matcher:Option<NativeRecordMatcher<I>>,spec:NativeVariantSpec,selection:Option<NativeVariantSelection>,tag:Option<usize>,record_len:Option<usize>,scan:usize,phase:u8,direct:bool,closing:bool,failed:bool,effect:NativeReceivingEffect,retirement_effect:NativeReceivingEffect<OriginalRetirementFailure>}
impl<I:NativeValueSource+?Sized>NativeVariantSelector<I>{
 pub fn new(spec:NativeVariantSpec)->Self{Self{binding:None,matcher:None,spec,selection:None,tag:None,record_len:None,scan:0,phase:0,direct:false,closing:false,failed:false,effect:Default::default(),retirement_effect:Default::default()}}
 pub fn result(&self)->Option<NativeVariantSelection>{if self.has_pending_recovery(){None}else{self.selection}}
 pub fn validate_input(&self,input:RetainedCloneRef<'_,I>)->Result<(),ValueError>{input.check_binding(&self.binding)?;Ok(())}
 pub fn demands(&self,input:RetainedCloneRef<'_,I>,body:usize,maximum:u64)->Result<RetirementDemand,ValueError>{
  if self.closing||self.has_pending_recovery(){return Err(invalid())}self.validate_input(input)?;if maximum==0||self.selection.is_some()||self.failed{return Ok(Default::default())}
  if !input.check_binding(&self.binding)?{return Ok(fixed(input.binding_copy_bytes()))}
  if let Some(m)=self.matcher.as_ref(){if self.phase==3&&!m.terminal_is_empty(){return self.settlement_demand(body)}if self.phase!=3&&m.result().is_none(){return nested(m.demands(input,body,maximum)?)}}
  Ok(fixed(match self.phase{0=>size_of::<u8>(),1=>size_of::<Option<NativeRecordMatcher<I>>>()+size_of::<Option<usize>>()+size_of::<u8>()+size_of::<bool>(),2=>if let Some(m)=self.matcher.as_ref(){match m.result().ok_or_else(invalid)?{NativeFieldMatch::Field(_) if self.tag.is_none()=>size_of::<Option<usize>>()+size_of::<u8>(),NativeFieldMatch::Missing=>size_of::<u8>(),_=>size_of::<bool>()}}else{size_of::<Option<NativeRecordMatcher<I>>>()+size_of::<u8>()+size_of::<bool>()},3=>size_of::<Option<NativeRecordMatcher<I>>>()+size_of::<usize>()+size_of::<u8>(),4=>size_of::<Option<NativeVariantSelection>>()+size_of::<u8>()+size_of::<bool>(),_=>return Err(invalid())}))
 }
 pub fn advance_work_demand(&self,input:RetainedCloneRef<'_,I>,body:usize,maximum:u64)->Result<u64,ValueError>{
  self.demands(input,body,maximum)?;if maximum==0||self.selection.is_some()||self.failed{return Ok(0)}
  if !input.check_binding(&self.binding)?{return Ok(selected_native_work(input.binding_work_demand(&self.binding)?,maximum))}
  if let Some(m)=self.matcher.as_ref(){if self.phase==3&&!m.terminal_is_empty(){return Ok(selected_native_work(self.settlement_work_demand(body)?,maximum))}if self.phase!=3&&m.result().is_none(){return m.advance_work_demand(input,body,maximum)}}
  let mut q=match self.phase{0=>1,1=>3,2=>2,3=>3,4=>2,_=>return Err(invalid())};
  if self.phase==1{for a in[NativeSourceAccess::VariantTag,NativeSourceAccess::TreeKind,NativeSourceAccess::RecordLen]{q=work_sum(q,input.get().accessor_work_demand(a)?)?}}
  Ok(selected_native_work(q,maximum))
 }
 pub fn capture_plan(&self)->Result<Option<semio_framework_value_native_decoding::NativeEffectCapturePlan>,ValueError>{
 if self.effect.has_pending_recovery(){return Ok(Some(self.effect.capture_plan()))}
 if self.retirement_effect.has_pending_recovery(){return Ok(Some(self.retirement_effect.capture_plan()))}
 if let Some(m)=self.matcher.as_ref(){if m.has_pending_recovery(){return m.capture_plan()}}
 if self.closing||self.selection.is_some()||self.failed{return Ok(None)}
 if let Some(m)=self.matcher.as_ref(){if self.phase==3&&!m.terminal_is_empty(){return Ok(Some(self.retirement_effect.capture_plan()))}if self.phase!=3&&m.result().is_none(){return m.capture_plan()}}
 Ok(Some(self.effect.capture_plan()))
 }
 pub fn has_pending_recovery(&self)->bool{self.effect.has_pending_recovery()||self.retirement_effect.has_pending_recovery()||self.matcher.as_ref().is_some_and(|m|m.has_pending_recovery())}
 pub fn pending_recovery(&mut self)->Option<NativeRecoveryLoan<'_>>{if self.effect.has_pending_recovery(){return self.effect.pending_recovery().map(NativeRecoveryLoan::Value)}if self.retirement_effect.has_pending_recovery(){return self.retirement_effect.pending_recovery().map(NativeRecoveryLoan::Retirement)}self.matcher.as_mut().and_then(|m|m.pending_recovery())}
 pub fn resume_recovery(&mut self,c:&mut NativeDecodeControl<'_>)->RetainedWorkOutcome<RetainedCloneProgress,OriginalReceivingPrimary>{if self.effect.has_pending_recovery(){c.finish_receiving(&mut self.effect)}else if self.retirement_effect.has_pending_recovery(){c.finish_retirement_receiving(&mut self.retirement_effect)}else if let Some(m)=self.matcher.as_mut(){m.resume_recovery(c)}else{RetainedWorkOutcome{result:Err(ValueError::invariant("variant selection has no pending recovery").into()),work:0}}}
 pub fn advance(&mut self,input:RetainedCloneRef<'_,I>,control:&mut NativeDecodeControl<'_>,body:usize,maximum:u64,g:RetainedCloneGrant)->RetainedWorkOutcome<RetainedCloneStep,OriginalReceivingPrimary>{
  let plan=(||{let maximum=native_work_limit(control,maximum)?;let q=self.advance_work_demand(input,body,maximum)?;let d=self.demands(input,body,maximum)?;Ok::<_,ValueError>((maximum,q,d))})();let(maximum,q,d)=match plan{Ok(v)=>v,Err(e)=>return RetainedWorkOutcome{result:Err(e.into()),work:0}};
  if self.selection.is_some(){return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(Default::default())),work:0}}if q==0||!retained_clone_grant_admits(g,d){return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0}}
  if self.phase==3&&self.matcher.as_ref().is_some_and(|m|!m.terminal_is_empty()){let Self{matcher,retirement_effect,..}=self;let t=control.receive_retirement(d,retirement_effect,d.capacity_bytes!=0,q,|grant,actual|{let mut none=None;let m=matcher.as_mut().expect("selected matcher remains retained");if !m.is_closing(){let t=m.begin_close_step(grant,q);RetainedWorkOutcome{result:t.result.map_err(Into::into),work:t.work}}else{m.close_step(child(grant),actual.unwrap_or(&mut none))}});return RetainedWorkOutcome{result:t.result.map(RetainedCloneStep::Progress),work:t.work}}
  if let Some(m)=self.matcher.as_mut(){if self.phase!=3&&m.result().is_none(){let t=m.advance(input,control,body,maximum,child(g));return RetainedWorkOutcome{result:t.result.map(|s|RetainedCloneStep::Progress(s.progress())),work:t.work}}}
  let Self{binding,matcher,spec,selection,tag,record_len,scan,phase,direct,failed,effect,..}=self;
  let t=control.receive_allocation(d,effect,false,q,|grant,_|{
   let grant=grant.restricted_by(g);if !retained_clone_grant_admits(grant,d){return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0}}
   let bound=match input.check_binding(binding){Ok(v)=>v,Err(e)=>return RetainedWorkOutcome{result:Err(e),work:0}};if !bound{let t=input.bind(binding,grant);return RetainedWorkOutcome{result:t.result.map(|p|RetainedCloneStep::Progress(p.unwrap_or_default())),work:t.work}}
   let mut copy=0;let mut work=0;let result=(||{
    match *phase{
     0=>{*phase=1;copy+=size_of::<u8>();work+=1},
     1=>{work+=input.get().accessor_work_demand(NativeSourceAccess::VariantTag)?;if input.get().variant_tag().is_some(){*direct=true;copy+=size_of::<bool>();work+=1;*matcher=Some(NativeRecordMatcher::new(spec.all,spec.count,NativeSchemaKeySource::VariantTag));copy+=size_of::<Option<NativeRecordMatcher<I>>>();work+=1;*phase=4;copy+=size_of::<u8>();work+=1}else if spec.tag.is_some(){work+=input.get().accessor_work_demand(NativeSourceAccess::RecordLen)?;*record_len=Some(input.get().record_len()?);copy+=size_of::<Option<usize>>();work+=1;*phase=2;copy+=size_of::<u8>();work+=1}else{work+=input.get().accessor_work_demand(NativeSourceAccess::TreeKind)?;let key=match input.get().tree_kind(){Some(NativeTreeKind::Text)=>NativeSchemaKeySource::Text,None=>NativeSchemaKeySource::EnumOrdinal,_=>{work+=input.get().accessor_work_demand(NativeSourceAccess::RecordLen)?;if input.get().record_len()?!=1{return Err(invalid())}NativeSchemaKeySource::RecordName(0)}};*matcher=Some(NativeRecordMatcher::new(if matches!(key,NativeSchemaKeySource::RecordName(_)){spec.data}else{spec.units},spec.count,key));copy+=size_of::<Option<NativeRecordMatcher<I>>>();work+=1;*phase=4;copy+=size_of::<u8>();work+=1}},
     2=>{if let Some(m)=matcher.as_ref(){match m.result().ok_or_else(invalid)?{NativeFieldMatch::Field(_)=>{if tag.is_some(){*failed=true;copy+=size_of::<bool>();work+=1;return Err(invalid())}*tag=Some(*scan);copy+=size_of::<Option<usize>>();work+=1},NativeFieldMatch::Ambiguous=>{*failed=true;copy+=size_of::<bool>();work+=1;return Err(invalid())},NativeFieldMatch::Missing=>{}}*phase=3;copy+=size_of::<u8>();work+=1}else{let count=record_len.ok_or_else(invalid)?;if *scan==count{let Some(rank)=*tag else{*failed=true;copy+=size_of::<bool>();work+=1;return Err(invalid())};*matcher=Some(NativeRecordMatcher::new(spec.all,spec.count,NativeSchemaKeySource::RecordText(rank)));*phase=4;copy+=size_of::<u8>();work+=1}else{*matcher=Some(NativeRecordMatcher::new(spec.tag.ok_or_else(invalid)?,1,NativeSchemaKeySource::Record(*scan)))}copy+=size_of::<Option<NativeRecordMatcher<I>>>();work+=1}},
     3=>{matcher.take();copy+=size_of::<Option<NativeRecordMatcher<I>>>();work+=1;*scan=scan.checked_add(1).ok_or_else(invalid)?;copy+=size_of::<usize>();work+=1;*phase=2;copy+=size_of::<u8>();work+=1},
     4=>{let NativeFieldMatch::Field(index)=matcher.as_ref().and_then(|m|m.result()).ok_or_else(invalid)?else{*failed=true;copy+=size_of::<bool>();work+=1;return Err(invalid())};if index>=spec.count{*failed=true;copy+=size_of::<bool>();work+=1;return Err(invalid())}*selection=Some(NativeVariantSelection{index,direct:*direct});copy+=size_of::<Option<NativeVariantSelection>>();work+=1;*phase=5;copy+=size_of::<u8>();work+=1},
     _=>return Err(invalid())
    }Ok(if selection.is_some(){RetainedCloneStep::Complete(progress(copy))}else{RetainedCloneStep::Progress(progress(copy))})
   })().map_err(|e:ValueError|e.with_retained_progress(progress(copy)));RetainedWorkOutcome{result,work}
  });RetainedWorkOutcome{result:t.result.map(|p|if selection.is_some(){RetainedCloneStep::Complete(p)}else{RetainedCloneStep::Progress(p)}),work:t.work}
 }
 pub fn begin_settlement_demand(&self)->Result<RetirementDemand,ValueError>{self.matcher.as_ref().map_or(Ok(Default::default()),|m|m.begin_close_demand())}
 pub fn begin_settlement_work_demand(&self)->Result<u64,ValueError>{self.matcher.as_ref().map_or(Ok(0),|m|m.begin_close_work_demand())}
 pub fn begin_settlement_step(&mut self,g:RetainedCloneGrant,maximum:u64)->RetainedWorkOutcome{self.matcher.as_mut().map_or(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(Default::default())),work:0},|m|m.begin_close_step(g,maximum))}
 pub fn settled(&self)->bool{self.matcher.is_none()}
 pub fn settlement_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if let Some(m)=self.matcher.as_ref(){if m.terminal_is_empty(){Ok(fixed(size_of::<Option<NativeRecordMatcher<I>>>()))}else if !m.is_closing(){m.begin_close_demand()}else{nested(m.close_demands(body)?)}}else{Ok(Default::default())}}
 pub fn settlement_work_demand(&self,body:usize)->Result<u64,ValueError>{self.settlement_demand(body)?;self.matcher.as_ref().map_or(Ok(0),|m|if m.terminal_is_empty(){Ok(1)}else if !m.is_closing(){m.begin_close_work_demand()}else{m.close_work_demand(body)})}
 pub fn settle_step(&mut self,g:RetainedCloneGrant,actual:&mut Option<usize>)->OriginalRetirementOutcome{let d=match self.settlement_demand(g.maximum_copy_bytes){Ok(d)=>d,Err(e)=>return RetainedWorkOutcome{result:Err(e.into()),work:0}};if !retained_clone_grant_admits(g,d){return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0}}let Some(m)=self.matcher.as_mut()else{return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(Default::default())),work:0}};if m.terminal_is_empty(){self.matcher.take();return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(receipt(d))),work:1}}if !m.is_closing(){let t=m.begin_close_step(g,1);return RetainedWorkOutcome{result:t.result.map_err(Into::into),work:t.work}}m.close_step(child(g),actual)}
 pub fn is_closing(&self)->bool{self.closing}
 pub fn begin_close_demand(&self)->Result<RetirementDemand,ValueError>{if self.has_pending_recovery(){return Err(invalid())}Ok(if self.closing{Default::default()}else{fixed(size_of::<bool>())})}
 pub fn begin_close_work_demand(&self)->Result<u64,ValueError>{self.begin_close_demand()?;Ok(u64::from(!self.closing))}
 pub fn begin_close_step(&mut self,g:RetainedCloneGrant,maximum:u64)->RetainedWorkOutcome{let d=match self.begin_close_demand(){Ok(d)=>d,Err(e)=>return RetainedWorkOutcome{result:Err(e),work:0}};if self.closing{return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(Default::default())),work:0}}if maximum==0||!retained_clone_grant_admits(g,d){return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0}}self.closing=true;RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(receipt(d))),work:1}}
 pub fn begin_close(&mut self)->Result<(),ValueError>{if self.has_pending_recovery(){return Err(invalid())}self.closing=true;Ok(())}
 pub fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Err(invalid())}if self.matcher.is_some(){return self.settlement_demand(body)}if self.binding.is_some(){return RetainedCloneBinding::close_demand(&self.binding,body)}Ok(if self.phase==0||self.phase==6{Default::default()}else{fixed(size_of::<u8>())})}
 pub fn close_work_demand(&self,body:usize)->Result<u64,ValueError>{self.close_demands(body)?;if self.matcher.is_some(){return self.settlement_work_demand(body)}if self.binding.is_some(){return RetainedCloneBinding::close_work_demand(&self.binding,body)}Ok(u64::from(self.phase!=0&&self.phase!=6))}
 pub fn close_step(&mut self,g:RetainedCloneGrant,actual:&mut Option<usize>)->OriginalRetirementOutcome{let d=match self.close_demands(g.maximum_copy_bytes){Ok(d)=>d,Err(e)=>return RetainedWorkOutcome{result:Err(e.into()),work:0}};if !retained_clone_grant_admits(g,d){return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0}}if self.matcher.is_some(){return self.settle_step(g,actual)}if self.binding.is_some(){let t=RetainedCloneBinding::close_one(&mut self.binding,g,actual);return RetainedWorkOutcome{result:t.result.map(RetainedCloneStep::Progress).map_err(Into::into),work:t.work}}if self.phase!=0&&self.phase!=6{self.phase=6;return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(receipt(d))),work:1}}RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(Default::default())),work:0}}
 pub fn terminal_is_empty(&self)->bool{!self.has_pending_recovery()&&self.binding.is_none()&&self.matcher.is_none()&&(self.phase==6||self.phase==0)}
}
impl<I:NativeValueSource+?Sized>Drop for NativeVariantSelector<I>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"native variant selector requires funded closure")}}
